3.4 Authentication and Security with Passport.js
Passport.js is authentication middleware for Node.js, offering 500+ strategies including Local, JWT,
Google OAuth, Facebook, GitHub, etc.
// JWT Authentication (most common for MEAN Stack)
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
// Register User
app.post('/register', async (req, res) => {
const hashedPassword = await bcrypt.hash(req.body.password, 12);
const user = await User.create({ ...req.body, password: hashedPassword });
res.status(201).json({ message: 'User created' });
});
// Login
app.post('/login', async (req, res) => {
const user = await User.findOne({ email: req.body.email });
const isValid = await bcrypt.compare(req.body.password, user.password);
if (!isValid) return res.status(401).json({ message: 'Invalid credentials' });
const token = jwt.sign({ userId: user._id }, process.env.JWT_SECRET, { expiresIn:
'7d' });
res.json({ token });
});
// Protect Routes (Auth Middleware)
const protect = (req, res, next) => {
const token = req.headers.authorization?.split(' ')[1]; // Bearer TOKEN
const decoded = jwt.verify(token, process.env.JWT_SECRET);
req.user = decoded;
next();
};
app.get('/profile', protect, (req, res) => res.json(req.user));
3.5 Error Handling and Logging
// Global Error Handler (must have 4 parameters)
app.use((err, req, res, next) => {
console.error(err.stack);
res.status(err.status || 500).json({
message: err.message || 'Internal Server Error',
...(process.env.NODE_ENV === 'development' && { stack: err.stack })
});
});
// Using Morgan for HTTP logging
const morgan = require('morgan');
app.use(morgan('dev')); // 'tiny', 'combined', 'dev'
